// @zeus-internal
"use client";
import { type RefObject, useEffect, useRef, useState } from "react";
export function useMenuState(
  value: boolean | undefined,
  initial: boolean,
  onChange?: (open: boolean) => void,
) {
  const [local, setLocal] = useState(initial);
  return [
    value ?? local,
    (next: boolean) => {
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ] as const;
}
export function useMenuDismiss(
  open: boolean,
  onChange: (open: boolean) => void,
  host: RefObject<HTMLElement | null>,
  trigger?: RefObject<HTMLElement | null>,
) {
  const latest = useRef(onChange);
  latest.current = onChange;
  useEffect(() => {
    if (!open) return;
    const pointer = (event: PointerEvent) => {
      if (!host.current?.contains(event.target as Node)) latest.current(false);
    };
    const key = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        latest.current(false);
        trigger?.current?.focus();
      }
    };
    document.addEventListener("pointerdown", pointer);
    document.addEventListener("keydown", key);
    return () => {
      document.removeEventListener("pointerdown", pointer);
      document.removeEventListener("keydown", key);
    };
  }, [open, host, trigger]);
}
export function MenuInternalStyles() {
  return (
    <style>{`
    .z-am-reset{font:inherit;color:inherit;border:0;background:none;text-decoration:none;cursor:pointer}
    .z-am-reset:focus-visible{outline:2px solid currentColor;outline-offset:5px}
    .z-am-roll{display:inline-flex;overflow:hidden;line-height:1.2}
    .z-am-roll>span{display:inline-block;position:relative;transition:transform .4s cubic-bezier(.2,.8,.2,1)}
    .z-am-roll>span:after{content:attr(data-letter);position:absolute;top:100%;left:0}
    a:hover .z-am-roll>span,a:focus-visible .z-am-roll>span{transform:translateY(-100%)}
    @keyframes z-am-character{from{transform:translateY(105%);opacity:0}to{transform:translateY(0);opacity:1}}
    [data-pill-open=true] .z-am-letter-entry{display:inline-block;animation:z-am-character var(--z-am-duration,.6s) cubic-bezier(.2,.8,.2,1) both}
    .z-am-pill-grid{display:grid;grid-template-columns:minmax(0,.75fr) minmax(0,1.25fr);gap:32px;padding:4px 32px 28px}
    .z-am-pill-image{width:100%;height:200px;object-fit:cover;border-radius:16px}
    .z-am-fs-layout{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:8vw;padding:100px 5vw 60px;min-height:100%;box-sizing:border-box}
    .z-am-fs-picture{width:100%;height:min(62vh,620px);object-fit:cover}
    .z-am-mega-mobile{display:none}
    .z-am-mega-groups{display:flex;gap:12px;align-items:center}
    .z-am-mega-columns{display:grid;grid-template-columns:repeat(var(--z-am-columns,3),minmax(0,1fr));gap:40px;padding:36px}
    @media(max-width:640px){.z-am-pill-grid{gap:20px;padding:0 20px 24px;grid-template-columns:minmax(0,.6fr) minmax(0,1fr)}.z-am-pill-image{height:180px}.z-am-fs-layout{grid-template-columns:1fr;gap:24px;padding-top:100px}.z-am-fs-picture{height:24vh}.z-am-mega-groups{display:none}.z-am-mega-mobile{display:block}.z-am-mega-columns{display:block;padding:20px}.z-am-mega-columns>div{margin-bottom:24px}}
    @media(prefers-reduced-motion:reduce){.z-am-animated,.z-am-animated *{animation-duration:.001ms!important;animation-delay:0s!important;transition-duration:.001ms!important;transition-delay:0s!important}}
  `}</style>
  );
}
export function MenuRollingLabel({
  text,
  stagger = 0.018,
  delay = 0,
}: {
  text: string;
  stagger?: number;
  delay?: number;
}) {
  return (
    <span className="z-am-roll" aria-hidden>
      {Array.from(text).map((letter, i) => (
        <span
          key={`${i}-${letter}`}
          data-letter={letter === " " ? "\u00a0" : letter}
          style={{ transitionDelay: `${i * 0.012}s` }}
        >
          <span className="z-am-letter-entry" style={{ animationDelay: `${delay + i * stagger}s` }}>
            {letter === " " ? "\u00a0" : letter}
          </span>
        </span>
      ))}
    </span>
  );
}

"use client";
import { type CSSProperties, useId, useLayoutEffect, useRef, useState } from "react";
import { MenuInternalStyles, MenuRollingLabel, useMenuDismiss, useMenuState } from "./menu-shared";
export interface MorphingPillLink {
  id: string;
  label: string;
  href: string;
  badge?: string;
}
export interface MorphingPillMenuProps {
  links: readonly MorphingPillLink[];
  image?: string;
  imageAlt?: string;
  imageHref?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onNavigate?: (link: MorphingPillLink) => void;
  duration?: number;
  stagger?: number;
  background?: string;
  color?: string;
  maxWidth?: number;
  className?: string;
  style?: CSSProperties;
}
export function MorphingPillMenu({
  links,
  image,
  imageAlt = "",
  imageHref,
  open,
  defaultOpen = false,
  onOpenChange,
  onNavigate,
  duration = 0.65,
  stagger = 0.018,
  background = "#292929",
  color = "#f4f2ec",
  maxWidth = 600,
  className,
  style,
}: MorphingPillMenuProps) {
  const [expanded, setExpanded] = useMenuState(open, defaultOpen, onOpenChange);
  const root = useRef<HTMLElement>(null),
    content = useRef<HTMLDivElement>(null),
    trigger = useRef<HTMLButtonElement>(null);
  const [height, setHeight] = useState(252);
  const id = useId();
  useMenuDismiss(expanded, setExpanded, root, trigger);
  useLayoutEffect(() => {
    const node = content.current;
    if (!node) return;
    const measure = () => setHeight(node.scrollHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  return (
    <div
      className={className}
      style={{ width: "100%", display: "flex", justifyContent: "center", ...style }}
    >
      <MenuInternalStyles />
      <nav
        ref={root}
        aria-label="Main navigation"
        data-pill-open={expanded}
        className="z-am-animated"
        style={
          {
            position: "relative",
            background,
            color,
            width: expanded ? `min(${maxWidth}px,100%)` : 120,
            height: expanded ? Math.min(height + 48, 10000) : 48,
            maxHeight: "calc(100dvh - 40px)",
            borderRadius: expanded ? 26 : 999,
            overflow: "hidden",
            transition: `width ${duration}s cubic-bezier(.2,.8,.2,1),height ${duration}s cubic-bezier(.2,.8,.2,1),border-radius ${duration}s`,
            "--z-am-duration": `${duration}s`,
          } as CSSProperties
        }
      >
        <div
          style={{ height: 48, display: "flex", justifyContent: "center", alignItems: "center" }}
        >
          <button
            ref={trigger}
            type="button"
            className="z-am-reset"
            aria-expanded={expanded}
            aria-controls={id}
            aria-label={expanded ? "Close navigation menu" : "Open navigation menu"}
            onClick={() => setExpanded(!expanded)}
            style={{
              minHeight: 44,
              padding: "0 18px",
              display: "flex",
              alignItems: "center",
              gap: 12,
              fontSize: 15,
            }}
          >
            {expanded ? "Close" : "Menu"}
            <span
              aria-hidden
              style={{
                width: 26,
                height: 26,
                borderRadius: 999,
                background: "#fff2",
                display: "grid",
                placeItems: "center",
                fontSize: 20,
                transform: expanded ? "rotate(45deg)" : "rotate(0deg)",
                transition: `transform ${duration}s`,
              }}
            >
              +
            </span>
          </button>
        </div>
        <div
          id={id}
          inert={!expanded}
          aria-hidden={!expanded}
          style={{
            overflow: "auto",
            height: "calc(100% - 48px)",
            opacity: expanded ? 1 : 0,
            transition: `opacity ${duration * 0.5}s`,
          }}
        >
          <div
            ref={content}
            className="z-am-pill-grid"
            style={!image ? { gridTemplateColumns: "1fr" } : undefined}
          >
            {image &&
              (imageHref ? (
                <a
                  href={imageHref}
                  aria-label={imageAlt || "View collection"}
                  onClick={() => setExpanded(false)}
                >
                  <img className="z-am-pill-image" src={image} alt={imageAlt} />
                </a>
              ) : (
                <img className="z-am-pill-image" src={image} alt={imageAlt} />
              ))}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                alignItems: "flex-start",
                minWidth: 0,
              }}
            >
              {links.map((link, index) => (
                <a
                  key={link.id}
                  className="z-am-reset"
                  href={link.href}
                  aria-label={link.label}
                  onClick={() => {
                    setExpanded(false);
                    onNavigate?.(link);
                  }}
                  style={{
                    fontSize: "clamp(20px,3vw,34px)",
                    letterSpacing: "-.045em",
                    lineHeight: 1.3,
                    minHeight: 44,
                    display: "flex",
                    alignItems: "center",
                    maxWidth: "100%",
                    gap: 10,
                  }}
                >
                  <span style={{ overflow: "hidden" }}>
                    <MenuRollingLabel
                      text={link.label}
                      stagger={stagger}
                      delay={index * stagger * 4}
                    />
                  </span>
                  {link.badge && (
                    <small style={{ color: "#ff653b", fontSize: 12, letterSpacing: 0 }}>
                      {link.badge}
                    </small>
                  )}
                </a>
              ))}
            </div>
          </div>
        </div>
      </nav>
    </div>
  );
}
